laboratory.referenceCode:
#include <iostream>
#include <vector>
int main() {
    int rows{}, cols{};
    if (!(std::cin >> rows >> cols) || rows < 0 || rows > 10 || cols < 0 || cols > 10) { std::cout << "invalid\n"; return 0; }
    std::vector<int> data(rows * cols);
    for (int& value : data) { if (!(std::cin >> value) || value < -1000 || value > 1000) { std::cout << "invalid\n"; return 0; } }
    std::cin >> std::ws;
    if (!std::cin.eof()) { std::cout << "invalid\n"; return 0; }
    long long total{};
    for (int value : data) { total += value; }
    std::cout << total << '\n';
    for (int r = 0; r < rows; ++r) {
        long long rowSum{};
        for (int c = 0; c < cols; ++c) { rowSum += data[r * cols + c]; }
        if (r != 0) { std::cout << ' '; }
        std::cout << rowSum;
    }
    std::cout << '\n';
}
